"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2942],{53114:n=>{n.exports=JSON.parse('{"functions":[{"name":"new","desc":"Creates a Routing for `parent`. Pins are read from the instance; for anything that isn\'t an audio instance, pass them.\\nComponents create their own Routing, so you rarely need this.","params":[{"name":"parent","desc":"The audio instance to route","lua_type":"Instance"},{"name":"pins","desc":"Pin types (from [Enums.Pin]) to use when `parent` isn\'t an audio instance","lua_type":"{ EnumItem }?"}],"returns":[{"desc":"","lua_type":"Routing"}],"function_type":"static","source":{"line":90,"path":"src/Orchestra/Components/Routing.luau"}},{"name":"Wire","desc":"Wires two explicit pins together, for example one channel of an [AudioChannelSplitter]. Allowed: Output to Input,\\nInput to Output.","params":[{"name":"from","desc":"Source instance, its [Enums.Pin] type, and pin name (nil for the default pin)","lua_type":"{ Instance: Instance, PinType: EnumItem, Pin: string? }"},{"name":"to","desc":"Target instance, its [Enums.Pin] type, and pin name (nil for the default pin)","lua_type":"{ Instance: Instance, PinType: EnumItem, Pin: string? }"}],"returns":[],"function_type":"method","source":{"line":162,"path":"src/Orchestra/Components/Routing.luau"}},{"name":"WireTo","desc":"Wires this instance\'s output into `to`. Errors if `to` has no input pins, or no input pin named `toPin`.","params":[{"name":"to","desc":"The audio instance to wire into, usually another component\'s `In`","lua_type":"Instance"},{"name":"toPin","desc":"Input pin on `to`, for example `\\"Sidechain\\"`. Defaults to its default input pin","lua_type":"string?"}],"returns":[],"function_type":"method","source":{"line":203,"path":"src/Orchestra/Components/Routing.luau"}},{"name":"WireFrom","desc":"Wires `from`\'s output into this instance. Errors if `from` has no output pins, or no output pin named `fromPin`.","params":[{"name":"from","desc":"The audio instance to wire from, usually another component\'s `Out`","lua_type":"Instance"},{"name":"fromPin","desc":"Output pin on `from`, for example `\\"Left\\"`. Defaults to its default output pin","lua_type":"string?"}],"returns":[],"function_type":"method","source":{"line":239,"path":"src/Orchestra/Components/Routing.luau"}},{"name":"Destroy","desc":"Destroys the Routing: every wire it created, every wire connected into its instance (those live under the source\'s\\n`AudioRouter`), and its `AudioRouter` folder.","params":[],"returns":[],"function_type":"method","source":{"line":273,"path":"src/Orchestra/Components/Routing.luau"}}],"properties":[],"types":[],"name":"Routing","desc":"Knows the input and output pins of one audio instance and creates `Wire`s from it. Every component that can be wired\\nhas one as its `Routing`.\\n\\n```lua\\nlayer.Routing:WireTo(reverb.In)            -- default pins\\nsource.Routing:WireTo(compressor.In, \\"Sidechain\\")\\n```","tags":["Base"],"source":{"line":80,"path":"src/Orchestra/Components/Routing.luau"}}')}}]);